// requires roster syncing; use EligibleForKADEmails() for that check.
DontSendKADEmails bool `datastore:"dont_send_kad_emails,noindex"`

// all entities inside of this entity group is also test data. Tracking
// test data accurately helps Product Analytics filter out test data in
// weekly backups.
IsTest bool `datastore:"is_test"`

//
// This can be useful for waiting to sync until our customers have finished
// setup, or shutting off syncing in case of emergency.
// "required" in python
RosterSyncingEnabled bool `datastore:"roster_syncing_enabled"`

func (m *District) SendKADEmails() bool {
	return !m.DontSendKADEmails
}

func (m *District) SetSendKADEmails(enable bool) {
	m.DontSendKADEmails = !enable
}

// EligibleForKADEmails reports whether this district may receive KAD emails
// (e.g. monthly admin progress emails).
//
// A district is ineligible if it has opted out via DontSendKADEmails or if
// roster syncing is turned off.
func (m *District) EligibleForKADEmails() bool {
	return m.SendKADEmails() && m.RosterSyncingEnabled

