// getEmailableDistrictsByCountry gets the districts in a country that are
// eligible to receive KAD emails. Can be filtered to only test districts
// or only non-test districts.
func getEmailableDistrictsByCountry(
	ctx interface {
		kacontext.Base
		datastore.KAContext
		log.KAContext
	},
	countryCode string,
	testDistrictsOnly bool,
) ([]*models.District, error) {
	ctx.Log().Info(
		"Querying all districts in country",
		log.Fields{"countryCode": countryCode},
	)

	query := datastore.NewQuery(models.DistrictKind).
		FilterField("country_code", "=", countryCode)
	districts, err := crud.GetAll[models.District](ctx, query)
	if err != nil {
		return nil, err
	}

	var emailable []*models.District
	for _, d := range districts {
		if d.IsTest != testDistrictsOnly {
			continue
		}
		// Skip districts that have opted out of KAD emails or have roster
		// syncing turned off.
		if !d.EligibleForKADEmails() {
			continue
		}

		emailable = append(emailable, d)
	}
	return emailable, nil

	return nil, err
